<?php

// Curated starting points. Shared days are copied into each user's independent plan.
// Exercise identity comes exclusively from the built-in library key.
$ex = fn (string $id, int $sets = 3, string $reps = '8–12', string $mode = 'reps', ?string $notes = null, ?string $superset = null) => [
    'key' => 'builtin:'.$id, 'sets' => $sets, 'reps' => $reps, 'tracking_mode' => $mode,
    'target_weight' => null, 'notes' => $notes, 'superset_group' => $superset,
];
$day = fn (string $title, string $focus, array $exercises, ?string $notes = null) => [
    'title' => $title, 'focus_area' => $focus, 'exercises' => $exercises,
    'notes' => $notes ?? 'Warm up before working sets. Rest between sets and adjust the routine to your ability.',
];
$plan = fn (string $key, string $name, string $level, string $focus, array $goals, int $duration, string $equipment, string $description, array $days) => [
    'key' => $key, 'name' => $name, 'level' => $level, 'primary_focus' => $focus,
    'goals' => $goals, 'duration' => $duration, 'equipment' => $equipment,
    'description' => $description, 'days' => $days, 'enabled' => true,
];

$dbA = $day('Full Body A', 'Full Body', [$ex('Dumbbell_Squat', 2), $ex('Dumbbell_Floor_Press', 2), $ex('Bent_Over_Two-Dumbbell_Row', 2), $ex('Plank', 2, '20–30 seconds', 'duration')]);
$dbB = $day('Full Body B', 'Full Body', [$ex('Dumbbell_Lunges', 2, '8–10', notes: 'Reps per leg.'), $ex('Dumbbell_One-Arm_Shoulder_Press', 2), $ex('Stiff-Legged_Dumbbell_Deadlift', 2), $ex('Cross-Body_Crunch', 2, '10–15')]);
$dbC = $day('Full Body C', 'Full Body', [$ex('Split_Squat_with_Dumbbells', 2, '8–10', notes: 'Reps per leg.'), $ex('Pushups', 2, '6–12'), $ex('Bent_Over_Two-Dumbbell_Row', 2), $ex('Butt_Lift_Bridge', 2, '12–15')]);
$bwA = $day('Movement Foundations', 'Full Body', [$ex('Bodyweight_Squat', 2, '10–15'), $ex('Pushups', 2, '5–10', notes: 'Use a comfortable range of motion; lower the reps as needed.'), $ex('Superman', 2, '8–12'), $ex('Plank', 2, '20–30 seconds', 'duration')]);
$bwB = $day('Legs & Core Foundations', 'Legs', [$ex('Bodyweight_Walking_Lunge', 2, '8–10', notes: 'Reps per leg.'), $ex('Butt_Lift_Bridge', 2, '12–15'), $ex('Cross-Body_Crunch', 2, '10–15'), $ex('Hamstring_Stretch', 2, '20–30 seconds', 'duration')]);
$bwC = $day('Full Body & Balance', 'Full Body', [$ex('Split_Squats', 2, '8–10', notes: 'Reps per leg.'), $ex('Pushups', 2, '5–10'), $ex('Superman', 2, '10–12'), $ex('Side_Bridge', 2, '15–25 seconds', 'duration', 'Hold each side.')]);
$mobA = $day('Easy Cardio & Hips', 'Cardio', [$ex('Trail_Running_Walking', 1, '15 minutes', 'duration', 'Walk at a comfortable, conversational pace.'), $ex('Standing_Hip_Circles', 2, '8–10'), $ex('Hamstring_Stretch', 2, '30 seconds', 'duration'), $ex('Childs_Pose', 2, '30 seconds', 'duration')]);
$mobB = $day('Mobility & Core', 'Mobility', [$ex('Cat_Stretch', 2, '30 seconds', 'duration'), $ex('Worlds_Greatest_Stretch', 2, '30 seconds', 'duration', 'Repeat on both sides.'), $ex('Plank', 2, '20–30 seconds', 'duration'), $ex('Shoulder_Stretch', 2, '30 seconds', 'duration')]);
$mobC = $day('Steady Movement & Recovery', 'Mobility', [$ex('Trail_Running_Walking', 1, '15 minutes', 'duration', 'Easy walking or gentle jogging.'), $ex('Bodyweight_Squat', 2, '10'), $ex('Cat_Stretch', 2, '30 seconds', 'duration'), $ex('Childs_Pose', 2, '30 seconds', 'duration')]);
$gymA = $day('Gym Foundations A', 'Full Body', [$ex('Leg_Press', 2), $ex('Dumbbell_Bench_Press', 2), $ex('Seated_Cable_Rows', 2), $ex('Plank', 2, '20–30 seconds', 'duration')]);
$gymB = $day('Gym Foundations B', 'Full Body', [$ex('Dumbbell_Squat', 2), $ex('Wide-Grip_Lat_Pulldown', 2), $ex('Dumbbell_Shoulder_Press', 2), $ex('Seated_Leg_Curl', 2, '10–15')]);
$gymC = $day('Gym Foundations C', 'Full Body', [$ex('Dumbbell_Lunges', 2), $ex('Incline_Dumbbell_Press', 2), $ex('Seated_Cable_Rows', 2), $ex('Standing_Calf_Raises', 2, '12–15')]);
$upperA = $day('Upper Strength', 'Chest', [$ex('Barbell_Bench_Press_-_Medium_Grip', 3, '5–8'), $ex('Seated_Cable_Rows', 3), $ex('Dumbbell_Shoulder_Press', 3), $ex('Dumbbell_Bicep_Curl', 2, '10–15', superset: 'A'), $ex('Triceps_Pushdown', 2, '10–15', superset: 'A')], 'Rest 2–3 minutes on the opening lift. Superset A pairs curls with pushdowns; rest after each pair.');
$lowerA = $day('Lower Strength', 'Legs', [$ex('Barbell_Squat', 3, '5–8'), $ex('Romanian_Deadlift', 3, '6–10'), $ex('Seated_Leg_Curl', 3, '10–15'), $ex('Standing_Calf_Raises', 3, '12–15'), $ex('Plank', 3, '30–45 seconds', 'duration')]);
$upperB = $day('Upper Hypertrophy', 'Back', [$ex('Incline_Dumbbell_Press', 3), $ex('Wide-Grip_Lat_Pulldown', 3), $ex('One-Arm_Dumbbell_Row', 3, '10–12'), $ex('Side_Lateral_Raise', 3, '12–15'), $ex('Face_Pull', 3, '12–15')]);
$lowerB = $day('Lower Hypertrophy', 'Legs', [$ex('Leg_Press', 3, '10–15'), $ex('Dumbbell_Lunges', 3, '10–12', notes: 'Reps per leg.'), $ex('Lying_Leg_Curls', 3, '10–15'), $ex('Seated_Calf_Raise', 3, '12–20'), $ex('Reverse_Crunch', 3, '12–15')]);
$push = $day('Push', 'Chest', [$ex('Barbell_Bench_Press_-_Medium_Grip', 3), $ex('Dumbbell_Shoulder_Press', 3), $ex('Incline_Dumbbell_Flyes', 3, '10–15'), $ex('Side_Lateral_Raise', 3, '12–15'), $ex('Triceps_Pushdown', 3, '10–15')]);
$pull = $day('Pull', 'Back', [$ex('Wide-Grip_Lat_Pulldown', 3), $ex('Seated_Cable_Rows', 3), $ex('Reverse_Flyes', 3, '12–15'), $ex('Dumbbell_Bicep_Curl', 3, '10–12'), $ex('Face_Pull', 2, '12–15')]);
$full = $day('Full Body Support', 'Full Body', [$ex('Dumbbell_Squat', 3), $ex('Dumbbell_Bench_Press', 3), $ex('One-Arm_Dumbbell_Row', 3), $ex('Plank', 3, '30–45 seconds', 'duration')]);
$cardio = $day('Conditioning & Core', 'Cardio', [$ex('Trail_Running_Walking', 1, '25 minutes', 'duration', 'Keep a steady pace you can sustain.'), $ex('Mountain_Climbers', 3, '30 seconds', 'duration'), $ex('Plank', 3, '30 seconds', 'duration'), $ex('Hamstring_Stretch', 2, '30 seconds', 'duration')]);
$gymCardio = $day('Gym Conditioning', 'Cardio', [$ex('Running_Treadmill', 1, '25 minutes', 'duration'), $ex('Bodyweight_Squat', 3, '15'), $ex('Mountain_Climbers', 3, '30 seconds', 'duration'), $ex('Childs_Pose', 2, '30 seconds', 'duration')]);
$bwUpper = $day('Bodyweight Upper & Core', 'Chest', [$ex('Pushups', 3, '10–15'), $ex('Push_Up_to_Side_Plank', 3, '6–10'), $ex('Superman', 3, '12–15'), $ex('Side_Bridge', 3, '30–45 seconds', 'duration', 'Hold each side.')]);
$bwLower = $day('Bodyweight Lower', 'Legs', [$ex('Split_Squats', 3, '10–15', notes: 'Reps per leg.'), $ex('Single_Leg_Glute_Bridge', 3, '10–15'), $ex('Bodyweight_Walking_Lunge', 3, '12–15'), $ex('Plank', 3, '30–45 seconds', 'duration')]);
$bwFull = $day('Bodyweight Full Body', 'Full Body', [$ex('Bodyweight_Squat', 3, '15–20'), $ex('Clock_Push-Up', 3, '6–10'), $ex('Superman', 3, '12–15'), $ex('Cross-Body_Crunch', 3, '15–20')]);
$heavyUpper = $day('Upper Heavy', 'Chest', [$ex('Barbell_Bench_Press_-_Medium_Grip', 4, '4–6'), $ex('Bent_Over_Barbell_Row', 4, '5–8'), $ex('Standing_Military_Press', 3, '5–8'), $ex('Wide-Grip_Lat_Pulldown', 3, '8–10')], 'Allow 2–3 minutes between working sets. Select your own working weights.');
$heavyLower = $day('Lower Heavy', 'Legs', [$ex('Barbell_Squat', 4, '4–6'), $ex('Romanian_Deadlift', 3, '5–8'), $ex('Leg_Press', 3, '8–10'), $ex('Standing_Calf_Raises', 3, '10–15')]);
$deadlift = $day('Deadlift & Posterior Chain', 'Legs', [$ex('Barbell_Deadlift', 3, '3–5'), $ex('Dumbbell_Lunges', 3, '8–10'), $ex('Lying_Leg_Curls', 3, '10–12'), $ex('Plank', 3, '45 seconds', 'duration')], 'Take full rest between deadlift working sets. Keep later accessory work controlled.');
$arms = $day('Arms & Shoulders', 'Arms', [$ex('Dumbbell_Shoulder_Press', 3), $ex('Dumbbell_Bicep_Curl', 3, '10–15', superset: 'A'), $ex('Triceps_Pushdown', 3, '10–15', superset: 'A'), $ex('Side_Lateral_Raise', 3, '12–20'), $ex('Reverse_Flyes', 3, '12–20')], 'Superset A pairs curls with pushdowns. Rest after each pair.');
$pushB = $day('Push Volume', 'Chest', [$ex('Incline_Dumbbell_Press', 4, '8–12'), $ex('Dumbbell_Shoulder_Press', 3, '10–12'), $ex('Side_Lateral_Raise', 4, '12–20'), $ex('Standing_Dumbbell_Triceps_Extension', 3, '10–15')]);
$pullB = $day('Pull Volume', 'Back', [$ex('Bent_Over_Barbell_Row', 4, '8–10'), $ex('Wide-Grip_Lat_Pulldown', 3, '10–12'), $ex('Face_Pull', 3, '15–20'), $ex('Incline_Dumbbell_Curl', 3, '10–15')]);
$bwAdvancedPush = $day('Bodyweight Push Strength', 'Chest', [$ex('Clock_Push-Up', 4, '8–12'), $ex('Push_Up_to_Side_Plank', 4, '8–12'), $ex('Pushups', 3, '15–25'), $ex('Side_Bridge', 3, '45–60 seconds', 'duration')], 'Control the lowering phase. All movements use floor space only.');
$bwAdvancedLegs = $day('Single-Leg Strength', 'Legs', [$ex('Split_Squats', 4, '12–20', notes: 'Pause at the bottom. Reps per leg.'), $ex('Single_Leg_Glute_Bridge', 4, '12–20'), $ex('Bodyweight_Walking_Lunge', 4, '15–20'), $ex('Plank', 3, '45–60 seconds', 'duration')]);
$bwAdvancedCore = $day('Posterior Chain & Core', 'Core', [$ex('Superman', 4, '15–20'), $ex('Single_Leg_Glute_Bridge', 4, '15–20'), $ex('Flutter_Kicks', 3, '45 seconds', 'duration'), $ex('Reverse_Crunch', 4, '15–20'), $ex('Side_Bridge', 3, '45 seconds', 'duration')]);
$bwAdvancedFull = $day('Full Body Density', 'Full Body', [$ex('Freehand_Jump_Squat', 3, '8–12'), $ex('Clock_Push-Up', 3, '10–15'), $ex('Mountain_Climbers', 4, '45 seconds', 'duration'), $ex('Superman', 3, '15–20')], 'Finish each movement with controlled form; rest between sets. Use regular squats if you prefer no jumping.');

return [
    $plan('full-body-2', 'Full Body — 2 Days', 'beginner', 'general_fitness', ['general_fitness', 'build_muscle', 'get_stronger'], 45, 'dumbbells', 'Two whole-body workouts with recovery days between them. Uses dumbbells and floor space, without a bench.', [$dbA, $dbB]),
    $plan('full-body', 'Full Body — 3 Days', 'beginner', 'build_muscle', ['build_muscle', 'general_fitness', 'get_stronger'], 45, 'dumbbells', 'Three varied whole-body workouts to build a consistent lifting habit. Dumbbells and floor space are enough.', [$dbA, $dbB, $dbC]),
    $plan('gym-foundations', 'Gym Foundations — 3 Days', 'beginner', 'get_stronger', ['get_stronger', 'general_fitness', 'build_muscle'], 45, 'full_gym', 'Learn gym movement patterns with a manageable mix of machines and free weights.', [$gymA, $gymB, $gymC]),
    $plan('bodyweight-foundations', 'Bodyweight Foundations — 3 Days', 'beginner', 'general_fitness', ['general_fitness', 'get_stronger', 'build_muscle'], 30, 'bodyweight', 'A simple introduction to squatting, pushing, hip work, and core stability. No equipment required.', [$bwA, $bwB, $bwC]),
    $plan('mobility', 'Conditioning & Mobility — 3 Days', 'beginner', 'mobility', ['mobility', 'general_fitness', 'endurance'], 30, 'bodyweight', 'Easy walking and dedicated mobility sessions for movement, flexibility, and a steady activity habit.', [$mobA, $mobB, $mobC]),
    $plan('upper-lower', 'Upper / Lower — 4 Days', 'intermediate', 'build_muscle', ['build_muscle', 'get_stronger'], 60, 'full_gym', 'Two upper and two lower sessions balance strength work with muscle-building volume.', [$upperA, $lowerA, $upperB, $lowerB]),
    $plan('push-pull-legs', 'Push / Pull / Legs — 3 Days', 'intermediate', 'build_muscle', ['build_muscle', 'get_stronger'], 60, 'full_gym', 'One dedicated push, pull, and lower-body session each week. A focused split with four free days.', [$push, $pull, $lowerB]),
    $plan('ppl-full-body', 'Push / Pull / Legs + Full Body — 4 Days', 'intermediate', 'build_muscle', ['build_muscle', 'general_fitness'], 60, 'full_gym', 'A focused three-day split plus a lighter whole-body session for another weekly practice of key movements.', [$push, $pull, $lowerA, $full]),
    $plan('mixed-fitness', 'Body Recomposition — 4 Days', 'intermediate', 'lose_fat', ['lose_fat', 'build_muscle', 'endurance', 'general_fitness'], 60, 'full_gym', 'Three resistance sessions and one conditioning session. Supports strength and activity alongside your body composition goals.', [$upperA, $lowerA, $full, $gymCardio]),
    $plan('strength', 'Strength — 4 Days', 'intermediate', 'get_stronger', ['get_stronger', 'build_muscle'], 60, 'full_gym', 'Lower-rep main lifts with supporting upper and lower work. Leave a recovery day between the two lower sessions.', [$heavyUpper, $heavyLower, $upperA, $deadlift]),
    $plan('hypertrophy', 'Hypertrophy — 4 Days', 'intermediate', 'build_muscle', ['build_muscle'], 60, 'full_gym', 'Muscle-focused push, pull, and two lower-body sessions, using moderate reps and isolation work.', [$push, $lowerB, $pullB, $lowerA]),
    $plan('bodyweight-strength', 'Bodyweight Strength — 4 Days', 'intermediate', 'get_stronger', ['get_stronger', 'build_muscle', 'lose_fat', 'general_fitness'], 45, 'bodyweight', 'Three bodyweight resistance sessions and a conditioning day. Uses floor space and an outdoor walking route.', [$bwUpper, $bwLower, $bwFull, $cardio]),
    $plan('endurance', 'Cardio & Conditioning — 4 Days', 'intermediate', 'endurance', ['endurance', 'lose_fat', 'general_fitness'], 45, 'bodyweight', 'Two steady conditioning days, supporting leg work, and a mobility day. No gym equipment required.', [$cardio, $bwLower, $day('Long Easy Cardio', 'Cardio', [$ex('Trail_Running_Walking', 1, '35 minutes', 'duration', 'Steady walking or jogging, at a pace you can sustain.'), $ex('Hamstring_Stretch', 2, '30 seconds', 'duration'), $ex('Childs_Pose', 2, '30 seconds', 'duration')]), $mobB]),
    $plan('ppl-6', 'Push / Pull / Legs — 6 Days', 'advanced', 'build_muscle', ['build_muscle', 'get_stronger'], 60, 'full_gym', 'Six weekly sessions covering each movement group twice, with different strength and volume emphases. Higher weekly commitment.', [$push, $pull, $lowerA, $pushB, $pullB, $lowerB]),
    $plan('upper-lower-arms', 'Upper / Lower + Arms — 5 Days', 'advanced', 'build_muscle', ['build_muscle', 'get_stronger'], 60, 'full_gym', 'Four upper/lower sessions plus focused arm and shoulder work. Spread the sessions to allow recovery.', [$heavyUpper, $heavyLower, $upperB, $lowerB, $arms]),
    $plan('powerbuilding', 'Powerbuilding — 5 Days', 'advanced', 'get_stronger', ['get_stronger', 'build_muscle'], 90, 'full_gym', 'Heavy squat, bench, and deadlift work alongside dedicated muscle-building sessions. Allow extra time for full rest on heavy days.', [$heavyUpper, $heavyLower, $pushB, $deadlift, $pullB]),
    $plan('advanced-hypertrophy', 'Advanced Hypertrophy — 5 Days', 'advanced', 'build_muscle', ['build_muscle'], 60, 'full_gym', 'Five volume-focused sessions with additional upper-body and arm work. A higher-volume option for established training routines.', [$pushB, $lowerB, $pullB, $lowerA, $arms]),
    $plan('strength-hypertrophy', 'Strength + Hypertrophy Hybrid — 5 Days', 'advanced', 'get_stronger', ['get_stronger', 'build_muscle', 'general_fitness'], 60, 'full_gym', 'Two heavy sessions followed by push, pull, and lower-body volume. Combines both emphases in one weekly split.', [$heavyUpper, $heavyLower, $push, $pull, $lowerB]),
    $plan('advanced-bodyweight', 'Advanced Bodyweight — 5 Days', 'advanced', 'get_stronger', ['get_stronger', 'build_muscle', 'endurance'], 45, 'bodyweight', 'Higher-volume push, single-leg, core, and conditioning work using floor space only. No pull-up bar required; customize with pulling exercises if equipment is available.', [$bwAdvancedPush, $bwAdvancedLegs, $bwAdvancedCore, $bwAdvancedFull, $cardio]),
];
